  },
  "alignments": [
    {
      "competencyUri": "urn:educateos:catalog:c3:C3.D2.His.1.9-12",
      "frameworkKey": "c3"
    },
    {
      "competencyUri": "urn:educateos:catalog:c3:C3.D2.Civ.4.9-12",
